import type { Meta, StoryObj } from '@storybook/react'
import { useState } from 'react'
import { SpliceSliderContext } from './splice-slider-context'

const TP53_CDS =
  ''

function Playground({ sequence }: { sequence: string }) {
  const [position, setPosition] = useState(Math.floor(sequence.length / 2))
  return (
    <div className="mx-auto w-full max-w-5xl p-4">
      <SpliceSliderContext
        sequence={sequence}
        position={position}
        onSnap={setPosition}
        onSelectionChange={() => {}}
      />
    </div>
  )
}

const meta = {
  title: 'DesignTool/SpliceSliderContext',
  component: Playground,
  parameters: { layout: 'fullscreen' },
} satisfies Meta<typeof Playground>

export default meta
type Story = StoryObj<typeof meta>

export const TP53: Story = { args: { sequence: TP53_CDS } }
